function openNameDialog(n,t){return new Promise(function(i){nameDialogResolve=i;document.getElementById("nameDialogTitle").textContent=n;const r=document.getElementById("nameDialogInput");r.value=t||"";document.getElementById("nameDialog").showModal();r.focus();r.select()})}function closeNameDialog(n){const i=document.getElementById("nameDialogInput").value.trim(),t=nameDialogResolve;nameDialogResolve=null;document.getElementById("nameDialog").close();t&&t(n?i:null)}function isValidName(n){return n===null||n===""?!1:n.indexOf("\\")>=0||n.indexOf("/")>=0?(Promethe.toast("Name cannot contain slashes.","error"),!1):!0}function htmlText(n){return String(n).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;")}function htmlAttr(n){return htmlText(n).replace(/"/g,"&quot;")}function onFileListClick(n){const t=n.target.closest("[data-action]");if(t){const i=t.getAttribute("data-action"),r=t.getAttribute("data-path");i==="open"?loadPath(r):i==="rename"?renameEntry(r,t.getAttribute("data-name")):i==="delete"&&deleteEntry(r)}}async function waitForMountReady(){for(;;){const n=await Promethe.api("mountready.json");if(!n.ok)throw new Error("Failed to check mount status.");const t=await n.json();if(t.ready===!0)return;await new Promise(function(n){window.setTimeout(n,100)})}}async function ensureDrivesMounted(){if(!drivesMounted){const n=await Promethe.api("mountdrives");if(!n.ok)throw new Error("Failed to request drive mount.");await waitForMountReady();drivesMounted=!0}}async function initializeFileManager(){const n=document.getElementById("fileList");n.textContent="Mounting drives...";try{await ensureDrivesMounted();await loadPath("")}catch(t){n.textContent="Failed to connect."}}function parentPath(n){if(!n||n.length<=3)return"";let t=n;t.endsWith("\\")&&(t=t.slice(0,-1));const i=t.lastIndexOf("\\");return i<=2,t.slice(0,i+1)}function pathSegments(n){return n?n.split("\\").filter(function(n){return n.length>0}):[]}function pathForSegments(n,t){if(t<=0)return"";const i=n.slice(0,t).join("\\");return i.charAt(i.length-1)===":"?i+"\\":i.endsWith("\\")?i:i+"\\"}function renderPathLink(n,t){const i=n.replace(/\\/g,"\\\\").replace(/'/g,"\\'");return'<a class="prom-file-dir" href="javascript:void(0)" onclick="loadPath(\''+i+"')\">"+t+"<\/a>"}function renderPathBar(n){const i=document.getElementById("currentPath"),t=document.getElementById("pathUp");if(i!=null){if(n){const t=pathSegments(n);let r=renderPathLink("","Root");for(let n=0;n<t.length;n++){const i=pathForSegments(t,n+1),u=n===t.length-1;r+=' <span class="prom-files-path-sep">/<\/span> ';r+=u?'<span class="prom-files-path-current">'+t[n]+"<\/span>":renderPathLink(i,t[n])}i.innerHTML=r}else i.textContent="Root";t!=null&&(n?(t.hidden=!1,t.onclick=function(){loadPath(parentPath(n))}):(t.hidden=!0,t.onclick=null))}}function isNavigableEntry(n){return n.dir===!0||isDriveRoot(n.path)}function entryIcon(n){return isNavigableEntry(n)?"📁 ":"📄 "}function isDriveRoot(n){if(!n||/^SDCARD:\\?$/i.test(n))return!0;const t=n.indexOf(":");return t===n.length-1}function updateUploadBar(){const n=document.getElementById("uploadBar");n!=null&&(n.hidden=currentPath.length===0)}async function loadPath(n){await ensureDrivesMounted();currentPath=n||"";renderPathBar(currentPath);updateUploadBar();const t=document.getElementById("fileList");t.textContent="Loading...";try{const u=currentPath?"files.json?"+encodeURIComponent(currentPath):"files.json",r=await Promethe.api(u);if(!r.ok)throw new Error("request failed");const i=await r.json();if(!i.entries||i.entries.length===0){t.innerHTML="<p>This folder is empty.<\/p>";return}let n='<table><thead><tr><th>Name<\/th><th>Size<\/th><th class="prom-file-actions">Actions<\/th><\/tr><\/thead><tbody>';for(let t=0;t<i.entries.length;t++){const r=i.entries[t],u=htmlAttr(r.path),e=htmlAttr(r.name),f=htmlText(r.name);if(n+="<tr>",isNavigableEntry(r)){const t=isDriveRoot(r.path)?"prom-file-dir prom-file-drive":"prom-file-dir";n+='<td class="prom-file-name"><a class="'+t+'" href="javascript:void(0)" data-action="open" data-path="'+u+'">'+entryIcon(r)+f+"<\/a><\/td>"}else n+='<td class="prom-file-name">'+entryIcon(r)+f+"<\/td>";n+="<td>"+(isNavigableEntry(r)?"-":Promethe.formatBytes(r.size))+"<\/td>";n+='<td class="prom-file-actions">';isNavigableEntry(r)||(n+='<a role="button" class="secondary" href="/api/downloadfile?'+encodeURIComponent(r.path)+'" download="'+f+'">Download<\/a>');isDriveRoot(r.path)===!1&&(isNavigableEntry(r)||(n+=" "),n+='<a role="button" class="outline" href="javascript:void(0)" data-action="rename" data-path="'+u+'" data-name="'+e+'">Rename<\/a>',n+=' <a role="button" class="outline" href="javascript:void(0)" data-action="delete" data-path="'+u+'">Delete<\/a>');n+="<\/td><\/tr>"}n+="<\/tbody><\/table>";t.innerHTML=n}catch(i){t.textContent="Failed to connect."}}async function deleteEntry(n){if(window.confirm("Delete "+n+"?"))try{const t=await Promethe.api("deletefile?"+encodeURIComponent(n));if(!t.ok)throw new Error("delete failed");Promethe.toast("Deleted.","success");loadPath(currentPath)}catch(t){Promethe.toast("Delete failed.","error")}}async function createFolder(){if(!currentPath){Promethe.toast("Open a drive first.","error");return}const n=await openNameDialog("New folder name","");if(isValidName(n)){const t=currentPath.endsWith("\\")?currentPath+n:currentPath+"\\"+n;try{const n=await Promethe.api("createdir?"+encodeURIComponent(t));if(!n.ok)throw new Error("create failed");Promethe.toast("Folder created.","success");loadPath(currentPath)}catch(i){Promethe.toast("Could not create folder.","error")}}}async function renameEntry(n,t){const i=await openNameDialog("Rename",t);if(isValidName(i)&&i!==t){const r=n.substring(0,n.lastIndexOf("\\")),u=r+"\\"+i;try{const t=new FormData;t.append("body",JSON.stringify({source:n,dest:u}));const i=await fetch("/api/rename",{method:"POST",body:t});if(!i.ok)throw new Error("rename failed");Promethe.toast("Renamed.","success");loadPath(currentPath)}catch(f){Promethe.toast("Rename failed.","error")}}}async function uploadSelectedFile(){const n=document.getElementById("uploadFile");if(!n.files||n.files.length===0){Promethe.toast("Choose a file first.","error");return}if(!currentPath){Promethe.toast("Open a folder before uploading.","error");return}const t=n.files[0],r=currentPath.endsWith("\\")?currentPath+t.name:currentPath+"\\"+t.name,i=new FormData;i.append("file",t);try{const t=await fetch("/api/uploadfile?"+encodeURIComponent(r),{method:"POST",body:i});if(!t.ok)throw new Error("upload failed");Promethe.toast("Upload complete.","success");n.value="";loadPath(currentPath)}catch(u){Promethe.toast("Upload failed.","error")}}let currentPath="",drivesMounted=!1,nameDialogResolve=null;window.onload=function(){document.getElementById("year").textContent=(new Date).getFullYear();initializeFileManager();document.getElementById("fileList").addEventListener("click",onFileListClick);document.getElementById("nameDialog").addEventListener("close",function(){if(nameDialogResolve){const n=nameDialogResolve;nameDialogResolve=null;n(null)}})};